for i,(slug,title,difficulty,category,minutes,xp,lesson,classification,scenario,goal,steps,hints,solution,fix,url) in enumerate(rows,1):
 definitions.append({'code':f'LAB{i:03}','slug':slug,'title':title,'difficulty':difficulty,'category':category,'minutes':minutes,'points':xp,'lesson_slug':lesson,'classification':classification,'scenario_md':scenario,'objectives':[goal,'Jelaskan akar masalah dan bandingkan dengan perbaikan secure.'],'instructions':['Pahami konsep melalui lesson terkait.','Baca skenario dan identitas dummy; semua pengujian hanya dalam sesi ini.',*steps,'Ambil flag yang muncul setelah kondisi lab terpenuhi.','Kirim flag untuk validasi server.','Baca penjelasan akar masalah dan contoh perbaikan.','Reset fixture bila ingin mengulang; riwayat kelulusan tetap tersimpan.'],'hints':hints,'solution_md':solution,'secure_code':fix,'sources':[{'title':classification+' — referensi primer','url':url}],'default_body':defaults[slug],'default_headers':{'X-Dummy-User':'customer_b','Content-Type':'application/json'},'enabled':True,'reviewed_at':None,'authored_at':'2026-10-24'})
for path,data in [('database/data/labs-sprint3.json',definitions),('database/data/lab-routes.json',contracts),('sandbox/contracts.json',contracts)]:
 (root/path).write_text(json.dumps(data,ensure_ascii=False,indent=2),encoding='utf-8')
